package com.luc4n3x.levyra.ui.i18n

internal data class PodcastCopy(
    val title: String,
    val searchHint: String,
    val subscriptions: String,
    val continueListening: String,
    val history: String,
    val discover: String,
    val subscribe: String,
    val subscribed: String,
    val episodes: String,
    val markPlayed: String,
    val markUnplayed: String,
    val removeFromHistory: String,
    val clearHistory: String,
    val noResults: String,
    val loadFailed: String,
    val loadMore: String,
    val played: String,
    val minutesLeft: String,
    val emptyLibrary: String
) {
    fun minutesLeft(minutes: Long): String = minutesLeft.replace("%d", minutes.toString())
    fun all(): List<String> = listOf(
        title, searchHint, subscriptions, continueListening, history, discover, subscribe, subscribed, episodes,
        markPlayed, markUnplayed, removeFromHistory, clearHistory, noResults, loadFailed, loadMore, played, minutesLeft, emptyLibrary
    )
}

